// Typed access to data/findings.json, generated by scripts/export_web_findings.py from
// experiments/results/. Never edit the JSON by hand; rerun the script.
import raw from '../data/findings.json';

export type RootValue = 'WIN' | 'LOSS' | 'DRAW' | 'UNKNOWN';

export interface Source {
  path: string;
  commit: string | null;
  dirty: boolean | null;
}

export interface SolveCell {
  n: number;
  k: number;
  m: number;
  abc: string;
  complete: boolean;
  states: number;
  root: RootValue;
  rank: number | null;
  source: string;
}

export interface MatchRow {
  games: number;
  win: number;
  draw: number;
  truncated: number;
  loss: number;
  win_rate: number;
  ci95: [number, number];
}

export interface DqnEval {
  board: number;
  steps: number | null;
  value_optimal: number | null;
  mae: number | null;
  states: number | null;
  vs_greedy: MatchRow;
  source: string;
}

export interface Effect {
  name: string;
  estimate: number;
  ci95: [number, number];
  holm: boolean;
}

export interface H3Run {
  run: string;
  board: number;
  seed: number;
  budget: number;
  final: number;
  first_below: number | null;
  stays_below_from: number | null;
  curve: [number, number][];
  source: string;
}

export interface Findings {
  solve: SolveCell[];
  hop_rule_change: { n: number; abc: string; root: RootValue; rank: number | null; source: string }[];
  ablation: {
    board: string;
    agents: [string, string];
    distinct_openings: number;
    matches: number;
    win_rate_effects: Effect[];
    length_cell_means: Record<string, number>;
    length_additive_prediction: number;
    length_measured_all_on: number;
    length_ab_interaction: number;
    length_ab_holm: boolean;
    b_draw_effect: number;
    b_length_effect: number;
    source: string;
  };
  hop_scorer: {
    board: string;
    games: number;
    win_rate_default: number;
    win_rate_hop: number;
    difference: number;
    ci95: [number, number];
    source: string;
  };
  h1: {
    board: string;
    positions: number;
    time_limit_s: number;
    threshold_pct: number;
    cells: { abc: string; mean_legal: number; mean_depth: number; branching_pct: number; depth_change: number }[];
    source: string;
  };
  h2: { threshold_warmup: number; threshold_pure: number; arms: (DqnEval & { arm: string })[] };
  h3: { threshold: number; runs: H3Run[] };
  rq1: { cells: (DqnEval & { abc: string })[]; default_111_seeds: (DqnEval & { seed: number })[] };
  dqn_by_board: (DqnEval & { rules: Record<string, boolean | number> })[];
  sources: Record<string, Source>;
}

export const findings = raw as unknown as Findings;

export const source = (id: string): Source => findings.sources[id];

/** "A + C" style label for a rule cell such as "101"; "none" for "000". */
export const abcLabel = (abc: string): string => {
  const on = ['A', 'B', 'C'].filter((_, i) => abc[i] === '1');
  return on.length ? on.join(' + ') : 'none';
};

export const pct = (x: number, digits = 1): string => `${(100 * x).toFixed(digits)}%`;

export const range = (xs: number[], digits = 3): string => {
  const lo = Math.min(...xs);
  const hi = Math.max(...xs);
  return lo === hi ? lo.toFixed(digits) : `${lo.toFixed(digits)}–${hi.toFixed(digits)}`;
};
